# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">MÜLK SURESİ (TEBÂREKE) AYET GRUPLARI VE TEMEL KONULARI</text>\n  <rect x="25" y="48" width="205" height="190" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="127" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">1 - 5. Ayetler</text>\n  <text x="40" y="98" font-size="11" fill="#1e3a8a">• Mutlak hükümranlık (el-Mülk)</text>\n  <text x="40" y="120" font-size="11" fill="#1e3a8a">• Ölüm ve hayatın gayesi:</text>\n  <text x="48" y="136" font-size="11" font-weight="bold" fill="#1d4ed8">Ahsen-i amel (En güzel iş)</text>\n  <text x="40" y="160" font-size="11" fill="#1e3a8a">• Yedi kat gökte kusursuz</text>\n  <text x="48" y="176" font-size="11" fill="#1e3a8a">uyum (çatlak/kusur yok)</text>\n  <rect x="40" y="192" width="175" height="32" rx="6" fill="#ffffff" stroke="#60a5fa"/>\n  <text x="127" y="212" text-anchor="middle" font-size="10" font-weight="bold" fill="#1e40af">Tevhid ve İmtihan Bilinci</text>\n  <rect x="247" y="48" width="205" height="190" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="349" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#991b1b">6 - 14. Ayetler</text>\n  <text x="262" y="98" font-size="11" fill="#7f1d1d">• İnkârcıların ahiret pişmanlığı</text>\n  <text x="262" y="120" font-size="11" fill="#7f1d1d">• <tspan font-weight="bold">Mülk, 10:</tspan> "Dinleseydik ve</text>\n  <text x="270" y="136" font-size="11" fill="#7f1d1d">aklımızı kullansaydık..."</text>\n  <text x="262" y="160" font-size="11" fill="#7f1d1d">• Gizlide Allah\'tan sakınanlara</text>\n  <text x="270" y="176" font-size="11" fill="#7f1d1d">mağfiret ve büyük mükâfat</text>\n  <rect x="262" y="192" width="175" height="32" rx="6" fill="#ffffff" stroke="#f87171"/>\n  <text x="349" y="212" text-anchor="middle" font-size="10" font-weight="bold" fill="#b91c1c">Akıl, Vahiy ve Sorumluluk</text>\n  <rect x="470" y="48" width="205" height="190" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="572" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">15 - 30. Ayetler</text>\n  <text x="485" y="98" font-size="11" fill="#14532d">• Yeryüzünün boyun eğdirilmesi</text>\n  <text x="485" y="120" font-size="11" fill="#14532d">• Rızık arayışı ve tevekkül</text>\n  <text x="485" y="142" font-size="11" fill="#14532d">• Kuşların uçuşunda ilahi kudret</text>\n  <text x="485" y="164" font-size="11" fill="#14532d">• <tspan font-weight="bold">Mülk, 30:</tspan> Suyun çekilmesi</text>\n  <text x="493" y="180" font-size="11" fill="#14532d">örneğiyle nimet tefekkürü</text>\n  <rect x="485" y="192" width="175" height="32" rx="6" fill="#ffffff" stroke="#4ade80"/>\n  <text x="572" y="212" text-anchor="middle" font-size="10" font-weight="bold" fill="#15803d">Kevni Ayetler ve Şükür</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">NEBE SURESİ (AMME) AYET GRUPLARI VE YENİDEN DİRİLİŞ BİLİNCİ</text>\n  <rect x="25" y="48" width="205" height="190" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="127" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">1 - 16. Ayetler</text>\n  <text x="40" y="98" font-size="11" fill="#78350f">• <tspan font-weight="bold">en-Nebeü\'l-Azîm:</tspan> Büyük haber</text>\n  <text x="40" y="120" font-size="11" fill="#78350f">• Yeryüzü beşik, dağlar kazık</text>\n  <text x="40" y="142" font-size="11" fill="#78350f">• Gece örtü, gündüz geçim vakti</text>\n  <text x="40" y="164" font-size="11" fill="#78350f">• Yağmurla canlanan bahçeler</text>\n  <rect x="40" y="192" width="175" height="32" rx="6" fill="#ffffff" stroke="#fbbf24"/>\n  <text x="127" y="212" text-anchor="middle" font-size="10" font-weight="bold" fill="#b45309">Kevni Kudret Delilleri</text>\n  <rect x="247" y="48" width="205" height="190" rx="10" fill="#fae8ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="349" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">17 - 30. Ayetler</text>\n  <text x="262" y="98" font-size="11" fill="#581c87">• <tspan font-weight="bold">Yevmü\'l-Fasl:</tspan> Ayırma/Hüküm günü</text>\n  <text x="262" y="120" font-size="11" fill="#581c87">• Sûr\'a üfürülüş ve kıyamet</text>\n  <text x="262" y="142" font-size="11" fill="#581c87">• Hesap beklemeyenlerin akıbeti</text>\n  <text x="262" y="164" font-size="11" fill="#581c87">• Amel defterinde tam kayıt</text>\n  <rect x="262" y="192" width="175" height="32" rx="6" fill="#ffffff" stroke="#c084fc"/>\n  <text x="349" y="212" text-anchor="middle" font-size="10" font-weight="bold" fill="#7e22ce">Kıyamet ve İlahi Adalet</text>\n  <rect x="470" y="48" width="205" height="190" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="572" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">31 - 40. Ayetler</text>\n  <text x="485" y="98" font-size="11" fill="#14532d">• Takva sahiplerine kurtuluş (Mefâz)</text>\n  <text x="485" y="120" font-size="11" fill="#14532d">• Cennette boş/yalan söz yok</text>\n  <text x="485" y="142" font-size="11" fill="#14532d">• <tspan font-weight="bold">Nebe, 40:</tspan> Kişinin elleriyle</text>\n  <text x="493" y="158" font-size="11" fill="#14532d">yaptığı amellerle yüzleşmesi</text>\n  <rect x="485" y="192" width="175" height="32" rx="6" fill="#ffffff" stroke="#4ade80"/>\n  <text x="572" y="212" text-anchor="middle" font-size="10" font-weight="bold" fill="#15803d">Mükâfat ve Muhasebe</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">BİRİNCİ ÜNİTE BÜTÜNCÜL ÖZETİ: KUR\'AN TARİHİ VE SURELER</text>\n  <rect x="25" y="48" width="315" height="192" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">KUR\'AN TARİHİ VE ANA KONULARI</text>\n  <text x="40" y="98" font-size="11" fill="#1e3a8a">• <tspan font-weight="bold">Nüzul Süreci:</tspan> 610 - 632 (23 yıl, müneccemen)</text>\n  <text x="40" y="120" font-size="11" fill="#1e3a8a">• <tspan font-weight="bold">Cem\' (Derleme):</tspan> Hz. Ebû Bekir dönemi (Mushaf)</text>\n  <text x="40" y="142" font-size="11" fill="#1e3a8a">• <tspan font-weight="bold">İstinsah (Çoğaltma):</tspan> Hz. Osman dönemi</text>\n  <text x="40" y="164" font-size="11" fill="#1e3a8a">• <tspan font-weight="bold">Ana Konular:</tspan> İnanç, İbadet, Ahlak, Muamelat/Kıssa</text>\n  <rect x="40" y="184" width="285" height="40" rx="6" fill="#ffffff" stroke="#60a5fa"/>\n  <text x="182" y="208" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">Korunma: Hifz (Ezber) + Kitâbet (Yazı)</text>\n  <rect x="360" y="48" width="315" height="192" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">MÜLK VE NEBE SURELERİ KARŞILAŞTIRMASI</text>\n  <text x="375" y="98" font-size="11" fill="#14532d">• <tspan font-weight="bold">Mülk Suresi:</tspan> 29. cüz başı, 30 ayet, Mekki</text>\n  <text x="385" y="116" font-size="11" fill="#14532d">Diğer adı: <tspan font-style="italic">Tebâreke</tspan> | Odak: Mülk ve imtihan</text>\n  <text x="375" y="142" font-size="11" fill="#14532d">• <tspan font-weight="bold">Nebe Suresi:</tspan> 30. cüz başı, 40 ayet, Mekki</text>\n  <text x="385" y="160" font-size="11" fill="#14532d">Diğer adı: <tspan font-style="italic">Amme</tspan> | Odak: Büyük haber (Kıyamet)</text>\n  <rect x="375" y="184" width="285" height="40" rx="6" fill="#ffffff" stroke="#4ade80"/>\n  <text x="517" y="208" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">Ortak Tema: Kevni deliller ve ahiret sorumluluğu</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
